Triggered by nanoclaw with:
POST /webhook/newsletter-pipeline
Body: { "content_file": "data/sample/newsletter_content.json", "generate_images": true, "image_prompt": "NYC cityscape" }

parameters.functionCode:
const body = $input.first().json;

const params = {
  content_file: body.content_file || 'data/sample/newsletter_content.json',
  generate_images: body.generate_images !== false,
  image_prompt: (body.image_prompt || 'NYC cityscape editorial photography professional').replace(/[`$();|&<>\\]/g, ' ').trim(),
  image_ratio: body.image_ratio || '16:9',
  timestamp: new Date().toISOString()
};

console.log('Pipeline parameters:', JSON.stringify(params, null, 2));
return [{ json: params }];

const result = $input.first().json;
if (result.exitCode !== 0) {
  throw new Error('Content validation failed:\n' + (result.stderr || result.stdout || 'unknown error'));
}
console.log('Validation passed:', result.stdout);
// Pass through the parameters from earlier
const params = $node['Set Pipeline Parameters'].json;
return [{ json: params }];

const cmdResult = $input.first().json;
const params = $node['Check Validation Result'].json;

let imagePath = null;

if (cmdResult.exitCode === 0) {
  try {
    const stdout = cmdResult.stdout || '';
    const jsonMatch = stdout.match(/\{[\s\S]*\}/);
    const parsed = JSON.parse(jsonMatch ? jsonMatch[0] : stdout);
    imagePath = parsed.images && parsed.images[0] ? parsed.images[0] : null;
  } catch (e) {
    console.warn('Could not parse image output — continuing without image:', e.message);
  }
} else {
  console.warn('Image generation failed — continuing without image.');
  console.warn(cmdResult.stderr);
}

return [{ json: { ...params, image_path: imagePath } }];

const cmdResult = $input.first().json;
const params = $node['Parse Image Result'].json;

if (cmdResult.exitCode !== 0) {
  throw new Error('HTML rendering failed:\n' + (cmdResult.stderr || cmdResult.stdout || 'unknown error'));
}

// Extract the output path from stdout
const stdout = cmdResult.stdout || '';
const pathMatch = stdout.match(/Preview saved:\s*(.+\.html)/);
const htmlPath = pathMatch ? pathMatch[1].trim() : 'data/output/ (check for latest .html file)';

const summary = {
  status: 'success',
  timestamp: params.timestamp,
  content_file: params.content_file,
  html_preview: htmlPath,
  image_path: params.image_path,
  message: 'Newsletter rendered successfully. Open the HTML file to review.'
};

console.log('Pipeline complete:', JSON.stringify(summary, null, 2));
return [{ json: summary }];
